from produire import produire,paras,table,steps
from medicaments import antramups
produire(1,[
('La sténose peptique est un rétrécissement de l’œsophage lié aux lésions du reflux. La {fibrose cicatricielle} peut gêner la progression des aliments.',paras('L’inflammation répétée peut conduire à un remodelage et à un rétrécissement, souvent distal. La dysphagie peut aussi comporter une composante inflammatoire réversible, distincte d’un obstacle fibreux fixé.', 'Le caractère peptique est un diagnostic causal à établir. Un antécédent de reflux ou une amélioration sous anti-sécrétoire ne permet pas d’exclure une lésion tumorale.')),
('La sténose est une complication possible du reflux, mais toute dysphagie sous reflux n’en est pas une. Les {données de contexte} ne justifient pas un diagnostic automatique.',paras('L’usage des inhibiteurs de la pompe à protons a modifié la fréquence et la sévérité des lésions peptiques. Les recommandations britanniques décrivent des sténoses souvent courtes et accessibles à une dilatation, avec des évolutions variables.', 'Aucune fréquence suisse comparable parmi toutes les causes de dysphagie n’est attribuée ici. Le retentissement dépend du diamètre, de l’inflammation, des adaptations alimentaires et de l’état nutritionnel.')),
('L’agression liée au reflux peut entretenir inflammation puis cicatrisation fibreuse. Les {mécanismes de dysphagie} expliquent les deux composantes du traitement.',paras('Une lumière rétrécie oppose un obstacle mécanique au bol alimentaire. Les solides peuvent devenir difficiles avant les liquides, mais ce profil reste un indice, pas une preuve.', 'La suppression de l’acidité favorise le contrôle de l’inflammation et diminue la récidive après dilatation. Elle ne supprime pas nécessairement une fibrose déjà constituée.', 'La dilatation élargit la lumière mais ne traite pas à elle seule la cause du reflux. L’efficacité durable dépend donc aussi du contrôle de la maladie sous-jacente.')),
('Une dysphagie supposée peptique peut être une impaction ou une tumeur. Les {signaux d’alarme} déterminent l’urgence du bilan.',table(['🚩 Constat','Conduite'],[['Blocage brutal avec salive impossible à avaler.','Prise en charge urgente d’une obstruction complète.'],['Progression, perte de poids, saignement ou anémie.','Endoscopie et recherche de cancer rapides.'],['Douleur thoracique sévère, fièvre ou dyspnée après dilatation.','Évaluation urgente d’une complication, notamment perforation.'],['Apports insuffisants ou déshydratation.','Soutien rapide et adaptation de la voie d’alimentation.']])) ,
('L’entretien précise reflux, dysphagie et évolution des apports. Les {questions utiles} recherchent aussi les causes alternatives.',paras('Demander brûlures, régurgitations, durée des symptômes et difficulté aux solides ou aux liquides. Rechercher progression, impactions, perte pondérale et évitement d’aliments.', 'Préciser traitements anti-sécrétoires, prise réelle, réponse et endoscopies antérieures. Rechercher atopie, radiothérapie, chirurgie, ingestion caustique et médicaments pouvant léser l’œsophage.', 'Une dysphagie intermittente avec impaction ou un contexte atopique peut orienter vers une œsophagite à éosinophiles. Une biopsie antérieure bénigne ne suffit pas si le tableau a changé.')),
('L’examen apprécie surtout le retentissement et les complications. Les {éléments cliniques} ne visualisent pas directement la sténose.',paras('Évaluer hydratation, poids, état général et capacité de gérer la salive. Rechercher signes respiratoires ou manifestations d’une complication aiguë.', 'L’examen buccal, cervical et neurologique aide à identifier une cause oropharyngée associée. Un examen externe normal ne permet pas d’écarter une obstruction œsophagienne.', 'Après dilatation, une douleur persistante ou croissante, une fièvre ou une difficulté respiratoire impose une évaluation sans attendre le contrôle prévu.')),
('Le rétrécissement œsophagien possède plusieurs causes. Les {profils comparatifs} orientent le bilan et les biopsies.',table(['Profil','Orientation'],[['Sténose distale avec maladie de reflux documentée.','Cause peptique possible.'],['Lésion irrégulière, progression et altération générale.','Cancer à exclure.'],['Impactions, anneaux ou sillons, parfois endoscopie normale.','Œsophagite à éosinophiles.'],['Anneau localisé avec dysphagie intermittente.','Anneau de Schatzki.'],['Antécédent de chirurgie, irradiation ou caustique.','Autre sténose cicatricielle.'],['Dysphagie persistante sans obstacle explicatif.','Trouble moteur ou autre mécanisme à rechercher.']])) ,
('Le diagnostic associe endoscopie et recherche histologique des causes alternatives. Les {conditions de confirmation} précèdent le choix de dilatation.',paras('Les recommandations britanniques demandent des biopsies des sténoses pour exclure malignité et œsophagite à éosinophiles. L’histoire de reflux et l’aspect de la lésion soutiennent ensuite l’origine peptique.', 'Si la sténose est serrée ou suspecte de cancer, il peut être préférable d’attendre les résultats avant dilatation. Des prélèvements négatifs avec signes atypiques justifient une nouvelle évaluation, parfois après imagerie ou échoendoscopie.')),
('Le bilan précise anatomie, cause et retentissement. Les {examens ciblés} orientent une procédure adaptée.',paras('9.a — Référence : endoscopie haute avec biopsies de la sténose et recherche de causes associées.', '9.b — Décrire longueur, localisation, diamètre estimé, franchissabilité et inflammation. Une anatomie complexe peut demander un transit ou une autre imagerie spécialisée.', '9.c — Si le résultat histologique ne concorde pas avec une suspicion tumorale, compléter le bilan plutôt que conclure à une bénignité certaine.', '9.d — Si la lumière est suffisamment ouverte mais la dysphagie persiste, considérer un trouble moteur et une manométrie selon le bilan. Évaluer parallèlement nutrition, hydratation et conséquences biologiques selon le terrain.')),
('L’{algorithme de sténose} associe exclusion de l’urgence et confirmation de la cause. Le traitement du reflux complète celui de l’obstacle.',steps('Impaction complète ou complication → filière urgente.', 'Dysphagie stable → endoscopie et biopsies, évaluation des apports.', 'Cause peptique retenue → traitement antisécrétoire adapté ; dilatation si obstacle symptomatique.', 'Organiser surveillance et traitement du reflux après la procédure.', 'Récidive ou persistance → revoir histologie, inflammation, anatomie et motricité avant escalade.')),
('Le traitement vise une alimentation suffisante et la prévention des récidives. Les {options spécialisées} associent contrôle acide et correction mécanique selon le besoin.',paras('11.A — Soulager la dysphagie, restaurer les apports et limiter impactions et récidives.', '11.B — Les recommandations européennes soutiennent un inhibiteur de la pompe à protons pour le reflux avec dysphagie et après dilatation d’une sténose peptique. L’information suisse suivante décrit l’oméprazole pour l’œsophagite de reflux et sa prophylaxie, sans inventer une dose spécifique de dilatation.', '@@MEDICAMENTS@@', 'Une dilatation par ballon ou bougie guidée est décidée et réalisée par un endoscopiste formé. Expliquer possibilité de séances répétées et risques, notamment perforation et saignement ; le choix technique dépend de l’anatomie.', '11.C — Contrôler la reprise des prises selon les consignes de l’équipe et surveiller douleur, fièvre, dyspnée et saignement. En cas de récidive, vérifier contrôle de l’inflammation et cause réelle avant de qualifier la sténose de réfractaire.', '11.D — Adapter provisoirement textures et apports, sans transformer une alimentation très réduite en solution durable. Planifier le suivi du reflux, de la déglutition, du poids et des médicaments, puis réévaluer toute aggravation.')),
('La prévention vise le contrôle du reflux et le repérage des récidives. Les {mesures durables} ne remplacent pas l’exploration d’un symptôme nouveau.',paras('Primaire : prise en charge adaptée du reflux et des facteurs individuels. Secondaire : explorer une dysphagie au lieu de multiplier les essais symptomatiques sans diagnostic.', 'Tertiaire : poursuivre le traitement indiqué après dilatation et surveiller le retour des symptômes ou la perte de poids. Une nouvelle impaction impose une réévaluation de la cause et du calibre.')),
('Un reflux connu ne prouve pas qu’une sténose est bénigne. Les biopsies recherchent notamment cancer et œsophagite à éosinophiles. Anti-sécrétoire et dilatation ont des objectifs complémentaires. Une récidive ou une douleur après procédure doit être réévaluée.', '')
],[('Une sténose peptique est-elle uniquement un spasme ?','Non : elle comporte un rétrécissement lié aux lésions et à la cicatrisation.'),('Un reflux ancien suffit-il pour exclure un cancer ?','Non.'),('Pourquoi prélever une sténose ?','Pour rechercher notamment malignité et œsophagite à éosinophiles.'),('Une biopsie négative suffit-elle si l’aspect reste suspect ?','Non : réévaluation, imagerie et nouveaux prélèvements peuvent être nécessaires.'),('Une difficulté aux solides prouve-t-elle la cause peptique ?','Non : elle oriente vers un obstacle sans en définir la cause.'),('Que signifie un blocage avec salive impossible à avaler ?','Une obstruction complète possible, nécessitant une prise en charge urgente.'),('L’anti-sécrétoire élargit-il toujours une fibrose constituée ?','Non : une dilatation peut être nécessaire.'),('La dilatation suffit-elle à contrôler le reflux ?','Non : le traitement de la cause reste important.'),('Quel traitement réduit les récidives après dilatation peptique ?','Un inhibiteur de la pompe à protons, adapté par le prescripteur.'),('Peut-on broyer les micropellets d’Antramups ?','Non : l’AIPS l’interdit même lorsque le comprimé est dispersé.'),('La dispersion autorise-t-elle une prise orale en obstruction complète ?','Non.'),('La durée de cicatrisation du reflux fixe-t-elle automatiquement l’arrêt après dilatation ?','Non : la prévention est individualisée.'),('Quels signes après dilatation exigent un avis urgent ?','Douleur importante ou croissante, fièvre, dyspnée ou saignement notamment.'),('Que rechercher si la dysphagie persiste malgré un calibre adéquat ?','Une inflammation persistante, une cause alternative ou un trouble moteur selon le bilan.')],(5,6,10,11),antramups)
